apple-redistribution-into-boxes:
class Solution:
    def minimumBoxes(self, apple: List[int], capacity: List[int]) -> int:
        total = sum(apple)
        capacity.sort(reverse=True)
        for i, c in enumerate(capacity):
            total -= c
            if total <= 0:
                return i + 1
        return len(capacity)

binary-tree-tilt:
class Solution:
    def findTilt(self, root: Optional[TreeNode]) -> int:
        self.total = 0
        def go(node):
            if not node:
                return 0
            l = go(node.left)
            r = go(node.right)
            self.total += abs(l - r)
            return l + r + node.val
        go(root)
        return self.total

button-with-longest-push-time:
class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        best_i = events[0][0]
        best_t = events[0][1]
        for j in range(1, len(events)):
            t = events[j][1] - events[j - 1][1]
            if t > best_t:
                best_t = t
                best_i = events[j][0]
        return best_i

calculate-digit-sum-of-a-string:
class Solution:
    def digitSum(self, s: str, k: int) -> int:
        while len(s) > k:
            s = ''.join(str(sum(int(c) for c in s[i:i + k])) for i in range(0, len(s), k))
        return int(s)

can-make-arithmetic-progression-from-seq:
class Solution:
    def canMakeArithmeticProgression(self, arr: List[int]) -> bool:
        arr.sort()
        d = arr[1] - arr[0]
        return all(arr[i] - arr[i - 1] == d for i in range(1, len(arr)))

categorize-box-according-to-criteria:
class Solution:
    def categorizeBox(self, length: int, width: int, height: int, mass: int) -> str:
        bulky = length * width * height >= 10 ** 9 or max(length, width, height) >= 10 ** 4
        heavy = mass >= 100
        if bulky and heavy:
            return 'Both'
        if bulky:
            return 'Bulky'
        if heavy:
            return 'Heavy'
        return 'Neither'

check-if-all-characters-have-equal-numbe:
class Solution:
    def areOccurrencesEqual(self, s: str) -> bool:
        from collections import Counter
        return len(set(Counter(s).values())) == 1

